-- =====================================================================
-- Demo: "Sound & Sport for Wellbeing" (โครงการสุขภาพกายใจ สานสายใยด้วย
-- ดนตรีและกีฬา), taken from its real poster and announcement. A finished
-- event of the previous fiscal / academic year (Fri 26 Dec 2568 = 2025).
--
-- 11.00–22.00 at ห้องกระจก อาคารเรียนรวมวิทยาศาสตร์ and the parking area of
-- อาคารวิทยาศาสตร์ 4; registration closed Mon 22 Dec 2568. No certificate.
-- The announcement registered people through a Google Form; here they
-- register in the system, so that link is left out. Budget, seats and who
-- is responsible follow the department's budget plan (แผนพัฒนานักศึกษา
-- ภาควิชาคอมพิวเตอร์ ปีงบประมาณ 2569, item 6).
--
-- Who took part, as they were then: every student now in year 2 or above
-- (today's year-1 students hadn't started yet), registered with the year
-- they were in at the time (one lower than now). Three didn't come.
--
-- Apply AFTER schema, seed, demo_organizer, seed_blacklist. Safe to run
-- again: it removes event 1051 (registrations and check-ins cascade) first.
--   docker exec -i cpsu-etms-mysql mysql --default-character-set=utf8mb4 -uroot cpsu_etms < database/seed_sound_sport.sql
-- =====================================================================

USE cpsu_etms;
SET NAMES utf8mb4;

DELETE FROM events WHERE id = 1051;

INSERT INTO events (id, title, description, category, subcategory, program, years, organizer_id, organizer_name, coordinator_id,
  day_mode, date_start, date_end, event_dates, event_times, time_range, reg_start, reg_end,
  attend_mode, place, capacity, budget_planned, budget_other, budget_actual,
  attendee_note, ask_dietary, meals, issue_certificate, refund_method, status, cycle_stage,
  email_on_register, email_before_event, email_after_event, created_at)
VALUES (1051,
  'Sound & Sport for Wellbeing โครงการสุขภาพกายใจ สานสายใยด้วยดนตรีและกีฬา',
  'ดนตรีก็โดน 🎶 กีฬาก็มันส์ 🏓 สนุกกันยกภาค! 🔥
ปีใหม่นี้มารีเฟรชกายใจไปด้วยกัน ✨

🎉 เชิญชวนนักศึกษาภาควิชาคอมพิวเตอร์ทุกชั้นปี ร่วมโครงการ “สุขภาพกายใจ สานสายใยด้วยดนตรีและกีฬา Sound & Sport for Wellbeing”
กิจกรรมแน่น ความสนุกจัดเต็ม ที่ชาวคอมฯ พลาดไม่ได้! 💻

🗓 วันศุกร์ที่ 26 ธันวาคม 2568
🕐 เวลา 11.00 – 22.00 น.
📍 ณ ห้องกระจก อาคารเรียนรวมวิทยาศาสตร์ และ ลานจอดรถอาคารวิทยาศาสตร์ 4 คณะวิทยาศาสตร์

❌ ลงทะเบียนภายในวันจันทร์ที่ 22 ธันวาคม 2568',
  'การแข่งขัน', 'กีฬาและดนตรี', 'all', NULL, 2, 'ผศ.โอภาส วงษ์ทวีทรัพย์', 1032,
  'single', '2025-12-26', NULL, NULL, NULL,
  '11.00–22.00 น.', '2025-12-08', '2025-12-22',
  'onsite', 'ห้องกระจก อาคารเรียนรวมวิทยาศาสตร์ และลานจอดรถอาคารวิทยาศาสตร์ 4 คณะวิทยาศาสตร์', 400,
  300000.00, NULL, 287450.00,
  'แต่งกายชุดลำลองหรือชุดกีฬา · นำขวดน้ำส่วนตัวมาด้วย', 1,
  'lunch,break_pm,dinner', 0, 'none', 'done', 4,
  1, 1, 0, '2025-12-05 10:00:00');

-- ------------------------------------------------------------------ registrants, with the year they were in then
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, food_allergy, dietary_pref, registered_at)
SELECT 105100 + ROW_NUMBER() OVER (ORDER BY u.id), 1051, u.id,
       CONCAT('นักศึกษาชั้นปีที่ ', CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) - 1, SUBSTRING(u.dept, LOCATE(' · ', u.dept))),
       IF(u.id IN (1002, 1011, 1019), 'absent', 'attended'),
       IF(u.id IN (1002, 1011, 1019), 0, 1),
       IF(u.id IN (1002, 1011, 1019), NULL, TIMESTAMP('2025-12-26', SEC_TO_TIME(10 * 3600 + 30 * 60 + (u.id % 50) * 60))),
       'onsite',
       CASE u.id WHEN 1003 THEN 'กุ้ง' WHEN 1015 THEN 'ถั่วลิสง' END,
       CASE u.id WHEN 1006 THEN 'ฮาลาล' WHEN 1020 THEN 'มังสวิรัติ' END,
       TIMESTAMP('2025-12-08' + INTERVAL (u.id % 14) DAY, '20:15:00')
FROM users u
WHERE u.role = 'student'
  AND u.dept REGEXP 'ชั้นปีที่ *[0-9]'
  AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 2
  AND u.id NOT IN (1004, 1016);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2025-12-26', r.checked_in_at FROM registrations r WHERE r.event_id = 1051 AND r.checked_in = 1;

-- ------------------------------------------------------------------ the poster (JPEG, 2048 x 2048, 1:1)
UPDATE events SET poster_url = 'data:image/jpeg;base64,' WHERE id = 1051;
